from format_lecon import Lesson,paras,steps,table,ABBR,D
from html import escape
import gzip
ABBR.update({'DMLA':'dégénérescence maculaire liée à l’âge','DMLAe':'dégénérescence maculaire liée à l’âge exsudative','DMLAn':'dégénérescence maculaire liée à l’âge néovasculaire','VEGF':'facteur de croissance de l’endothélium vasculaire','OCT':'tomographie par cohérence optique','MAVC':'meilleure acuité visuelle corrigée','OVCR':'occlusion de la veine centrale de la rétine','OBVR':'occlusion de branche veineuse rétinienne','OMD':'œdème maculaire diabétique','mNVC':'néovascularisation choroïdienne myopique','NVCm':'néovascularisation choroïdienne myopique','EMA':'Agence européenne des médicaments'})
notice=gzip.open(D.parents[1]/'ressources_ia/aips/fi_fr/62393002.txt.gz','rt').read().splitlines()
def q(start):
 found=[s for s in notice if s.startswith(start)];assert len(found)==1,(start,len(found))
 s=found[0].removeprefix('· ')
 return '<blockquote><p>« '+escape(s)+' »</p></blockquote>'
l=Lesson('Dégénérescence maculaire liée à l’âge',5)
eylea=l.subwindow('eylea2','Aflibercept : présentation 2 mg/50 µl et règles suisses',paras('Cette fenêtre concerne exclusivement Eylea 2 mg/50 µl, solution à 40 mg/ml, pour la forme exsudative de la dégénérescence maculaire liée à l’âge. La seringue préremplie relève de Swissmedic 62393 et le flacon de 62397. La clé documentaire 62393002 utilisée dans les archives n’est pas un troisième numéro d’autorisation.',
'Les présentations à 8 mg/70 µl sont distinctes. Ne pas leur appliquer le volume, le calendrier ou la préparation décrits ici. Ce choix pédagogique d’une présentation documentée ne prétend pas classer tous les produits disponibles ni remplacer la décision du rétinologue.')+
'<h3>Indication, voie et calendrier</h3>'+q('Traitement de la forme exsudative')+q('La préparation ne doit être utilisée')+q('Eylea 2 mg dans 50 µl est administré par injection toutes les 4 semaines pendant les trois premiers mois.')+q('En cas de détérioration des paramètres')+q("Un examen de contrôle est nécessaire dans le cadre de chaque traitement. Des contrôles supplémentaires sont recommandés en fonction de l'état du patient selon l'appréciation du médecin traitant.")+q('Des intervalles au-delà de quatre mois')+
'<h3>Contre-indications</h3>'+q('· Hypersensibilité connue')+q('· Infection oculaire')+q('· Inflammation intraoculaire')+q('· Grossesse, allaitement.')+
'<h3>Âge, reins et foie</h3>'+q("Les données de sécurité et d'efficacité ne sont disponibles que")+q('Les études cliniques ont été menées surtout')+q("Aucune étude spécifique n'a été menée chez les patients présentant des troubles")+paras('La rétinopathie du prématuré est une autre indication, avec dispositif et dose propres. Elle ne justifie aucune extrapolation pédiatrique de ce schéma de DMLA adulte.')+
'<h3>Grossesse, allaitement et contraception</h3>'+q('Les femmes en âge de procréer')+q("Il n'existe pas de données concernant l'emploi chez la femme enceinte.")+q("Les études menées chez l'animal ont montré, après utilisation systémique")+q("C'est pourquoi Eylea ne doit pas être utilisé pendant la grossesse.")+q('Basé sur des données humaines très limitées')+q("Par mesure de précaution, l'allaitement n'est pas recommandé")+paras('La rubrique Contre-indications mentionne grossesse et allaitement. La formulation plus nuancée de la rubrique Allaitement ne doit pas être transformée en permission générale d’utilisation.')+
'<h3>Précautions et surveillance</h3>'+paras('Les citations suivantes mentionnent le facteur de croissance de l’endothélium vasculaire (VEGF). Elles évoquent aussi l’occlusion de la veine centrale de la rétine (OVCR), l’occlusion de branche veineuse rétinienne (OBVR) et l’œdème maculaire diabétique (OMD). Ces autres indications ne doivent pas être confondues avec la DMLA.')+q('Les injections intravitréennes peuvent entraîner')+q('Les patients doivent être avisés de signaler')+q('Une augmentation de la pression intraoculaire a été observée')+q("L'aflibercept étant une protéine thérapeutique")+q('Des effets indésirables systémiques incluant')+q("La sécurité et l'efficacité du traitement par Eylea administré simultanément")+q("Les données disponibles sont limitées concernant l'utilisation d'Eylea")+q("Les facteurs de risque associés au développement d'une déchirure")+
'<h3>Suspension</h3>'+q('Dans les cas suivants, le traitement doit être suspendu')+q('· diminution de la meilleure acuité')+q('· décollement de la rétine rhegmatogène')+q('· déchirure rétinienne;')+q('· hémorragie sous-rétinienne')+q('· chirurgie intraoculaire réalisée')+paras('Suspendre l’injection ne signifie pas attendre sans soins devant une complication. Une suspicion d’infection ou de décollement requiert sa prise en charge urgente. La décision de reprise est médicale.')+
'<h3>Préparation et prévention du surdosage</h3>'+q('En règle générale, il convient de garantir')+q("Chaque seringue préremplie ou flacon ne doit être utilisé(e)")+q('La solution non utilisée doit être éliminée')+q("La seringue préremplie contient un volume supérieur à la dose recommandée de 2 mg d'aflibercept (équivalente")+q("L'injection de la totalité du volume contenu dans la seringue préremplie pourrait résulter en un surdosage. Pour expulser")+q('La pression intraoculaire peut augmenter lors')+q("Afin d'assurer la traçabilité")+q('Contrôler la solution injectable visuellement')+q("Ne pas utiliser si une partie de la seringue préremplie")+
paras('Les étapes détaillées d’assemblage et de manipulation sont à appliquer dans la notice de la présentation utilisée. Le repère de dose n’autorise pas l’injection du contenu entier. La préparation relève d’une équipe formée, avec accès immédiat au traitement d’une hyperpression.')+
'<h3>Après injection</h3>'+q("Après l'injection intravitréenne, instruire les patients adultes")+q("L'injection intravitréenne et les examens oculaires y étant associés"),(48,))
l.add('La {dégénérescence maculaire liée à l’âge} (DMLA) atteint la région centrale de la rétine. Elle peut altérer lecture, reconnaissance des visages et perception des détails. Une déformation nouvelle ou une baisse centrale récente exige un contact ophtalmologique rapide.',paras('La macula permet la vision fine centrale. Une atteinte maculaire peut produire des lignes ondulées, appelées métamorphopsies, ou une zone centrale manquante, appelée scotome. La conservation de la vision périphérique ne supprime pas le handicap.',
'Une maladie liée à l’âge ne correspond pas à un vieillissement normal qu’il faudrait accepter sans examen. Le diagnostic précise le stade et la présence éventuelle d’une composante néovasculaire traitable. Une autre cause de baisse visuelle peut coexister.'),(7,43,47))
l.add('L’{âge et le terrain} orientent le risque sans établir le diagnostic. Le tabagisme et les facteurs génétiques sont notamment associés à la maladie. Les sources consultées ne fournissent pas une fréquence suisse comparable pour tous les diagnostics de cette leçon.',paras('La DMLA concerne surtout les personnes de plus de 50 ans et sa probabilité augmente avec l’âge. Rechercher les antécédents familiaux, le tabac et la maladie de l’autre œil. L’absence de symptôme peut refléter une compensation par l’œil qui voit mieux.',
'Une baisse chez un patient âgé n’est pas automatiquement une DMLA : cataracte, anomalie réfractive et atteinte du nerf optique doivent rester envisagées. Le contexte permet de prioriser les examens sans remplacer les constatations rétiniennes.'),(43,47))
l.add('Les {bases maculaires} expliquent les deux grandes formes évolutives. L’atrophie détruit progressivement des cellules utiles à la vision. La néovascularisation peut produire fuite liquidienne et hémorragie, avec une dégradation plus rapide.',table(['Structure ou mécanisme','Rôle ou atteinte','Conséquence'],[
['Macula et photorécepteurs','Région centrale permettant l’analyse des détails et des couleurs.','Atteinte de lecture et de reconnaissance, parfois malgré une périphérie conservée.'],
['Épithélium pigmentaire rétinien','Couche de soutien des photorécepteurs.','Sa dégénérescence participe à la forme atrophique.'],
['Néovaisseaux et perméabilité','Vaisseaux anormaux responsables de fuite ou de saignement.','Liquide et hémorragie peuvent menacer rapidement la vision centrale.'],
['Facteur de croissance de l’endothélium vasculaire, VEGF','Signal impliqué dans la croissance et la perméabilité vasculaires.','Son inhibition vise la composante néovasculaire ; elle ne régénère pas les cellules déjà perdues.']
])+paras('Les signes précoces et les formes avancées ne doivent pas être confondus. Le stade, l’activité et la localisation importent pour la décision. Une même personne peut avoir des situations différentes dans ses deux yeux.'),(43,45,47,48))
l.add('Les {signes urgents} sont toute modification récente de la vision centrale et les symptômes après injection. Une DMLA connue ne justifie pas d’attendre le prochain rendez-vous devant un changement. Une perte brutale, un rideau ou des signes neurologiques reprennent le tri immédiat du cours général.',paras('Une déformation nouvelle des lignes ou une tache centrale récente peut annoncer une activité néovasculaire. Contacter rapidement l’équipe, sans attendre qu’un autotest devienne plus anormal. L’absence de douleur n’est pas rassurante à elle seule.',
'Après injection, douleur, rougeur, photophobie ou baisse visuelle nécessitent un avis urgent. Ne pas limiter cette vigilance aux premières heures ou à une fenêtre de 72 heures. Une infection, une hyperpression ou une lésion rétinienne doit être évaluée sans attendre la prochaine injection.'),(4,7,43,44,48))
l.add('L’anamnèse évalue le {retentissement et l’évolution de chaque œil}. Elle recherche les symptômes nouveaux et les traitements déjà reçus. Les difficultés de suivi doivent être identifiées avant qu’elles n’interrompent les soins.',steps('Préciser début, progression, gêne de lecture, lignes déformées et tache centrale, œil par œil.','Comparer au niveau antérieur et rechercher une modification depuis le dernier examen.','Noter produit injecté, présentation, œil traité, date et réponse observée.','Recenser allergies, infection oculaire, inflammation et interventions récentes ou prévues.','Signaler antécédents vasculaires, traitements habituels et difficultés à se déplacer ou à comprendre les consignes.','Évaluer l’autonomie, l’éclairage, les aides de lecture et la charge des rendez-vous.'),(13,43,44,48))
l.add('L’{examen ophtalmologique} associe mesure de la vision et examen rétinien. Il apprécie la macula et recherche les causes associées de baisse visuelle. Une grille d’Amsler normale ne suffit pas à exclure une activité de la maladie.',paras('Mesurer chaque œil avec correction adaptée et comparer aux mesures antérieures. Rechercher une déformation ou un scotome central et examiner les milieux oculaires. Un cristallin opaque peut coexister avec une lésion maculaire.',
'Le fond d’œil apprécie les lésions maculaires, une hémorragie et les autres anomalies. L’imagerie est choisie pour caractériser la forme et guider le traitement. Une difficulté à réaliser un test ne constitue pas un résultat négatif.',
'Après dilatation, respecter les consignes de conduite et organiser le retour. Les besoins pratiques du patient font partie de la qualité de l’examen et du suivi.'),(13,43))
l.add('L’{approche syndromique} distingue forme atrophique, activité néovasculaire et complication thérapeutique. Le symptôme de flou ne détermine pas à lui seul le traitement. L’examen doit aussi rechercher une autre cause.',table(['Présentation','Question','Décision'],[
['Gêne centrale lente avec lésions atrophiques','Quel stade et quel handicap ?','Suivi, prévention adaptée et réadaptation visuelle.'],
['Déformation ou scotome récent','Existe-t-il une néovascularisation active ?','Évaluation rapide avec imagerie dirigée.'],
['Baisse brusque ou rideau','Une autre urgence rétinienne ou vasculaire est-elle présente ?','Parcours urgent du cours général.'],
['Douleur ou rougeur après injection','Infection, inflammation ou hyperpression ?','Évaluation immédiate, pas de simple attente.'],
['Vision limitée malgré maladie inactive','Atrophie, cicatrice, cataracte ou autre facteur ?','Réévaluer le bénéfice des soins et les aides utiles.']
]),(7,13,43,44,47,48))
l.add('Le diagnostic positif demande une {atteinte maculaire caractérisée}. La décision thérapeutique précise l’activité et le stade, pas seulement le nom de DMLA. Un résultat d’imagerie s’interprète avec la vision et l’examen.',paras('Le diagnostic s’appuie sur l’examen rétinien et l’imagerie spécialisée. Une baisse centrale ou des métamorphopsies orientent, mais ne sont pas spécifiques à cette maladie. L’âge seul ne remplace pas la caractérisation de la lésion.',
'L’activité néovasculaire, la présence de liquide ou d’hémorragie et les lésions irréversibles influencent le bénéfice attendu. Une maladie stable sous traitement n’est pas automatiquement guérie. Le calendrier est réévalué par le spécialiste.'),(13,43,47,48))
l.add('Les {examens complémentaires} décrivent la macula et son évolution. La tomographie par cohérence optique guide souvent la surveillance. Une angiographie est demandée lorsque la question vasculaire la justifie.',
'<h3>9.a — Référence diagnostique</h3>'+paras('Le diagnostic résulte de l’examen ophtalmologique et de l’imagerie adaptée à la forme suspectée. La grille d’Amsler aide à repérer un changement, mais ne suffit pas à classer une lésion ou à choisir une injection.')+
'<h3>9.b — Première intention</h3>'+paras('Mesurer l’acuité et examiner le fond d’œil. La tomographie par cohérence optique (OCT) donne des coupes de la rétine, repère du liquide ou des anomalies maculaires et permet des comparaisons au suivi.')+
'<h3>9.c — Examens dirigés</h3>'+paras('Une angiographie avec colorant peut préciser la vascularisation et les fuites. Elle répond à une indication clinique, avec vérification des précautions propres au produit. Aucun colorant ni schéma d’injection intraveineuse n’est prescrit ici.')+
'<h3>9.d — Seconde intention</h3>'+paras('Si la vision et l’imagerie sont discordantes, rechercher une cause associée ou une autre maladie maculaire. Le bilan est réorienté selon l’examen. Une répétition automatique du même test ne remplace pas cette réévaluation.'),(13,43))
l.add('L’{arbre décisionnel} commence par le changement clinique et la forme de la maladie. Une activité néovasculaire traitable appelle une prise en charge rapide. Le suivi et les aides visuelles restent utiles quelle que soit l’option retenue.',steps('Si perte brutale, rideau ou signe neurologique, alors suivre immédiatement le parcours d’urgence.','Si métamorphopsie ou scotome central nouveau, alors contacter rapidement l’ophtalmologie.','Si activité néovasculaire confirmée, alors discuter le traitement intravitréen après vérification du produit et des contre-indications.','Si forme atrophique sans activité néovasculaire, alors organiser suivi, prévention et réadaptation adaptés au stade.','Si traitement en cours, alors évaluer vision et morphologie avant de modifier l’intervalle.','Si douleur, rougeur ou baisse après injection, alors faire rechercher immédiatement une complication.'),(7,13,42,43,44,48))
l.add('La {prise en charge suisse} vise à préserver la vision utile et l’autonomie. Les anti-VEGF traitent la composante néovasculaire lorsqu’ils sont indiqués. Le produit, sa présentation, son calendrier et les raisons de suspension doivent être vérifiés avant chaque administration.',
'<h3>11.A — But</h3>'+paras('Réduire l’activité de la maladie lorsqu’un traitement peut agir, prévenir une perte supplémentaire et soutenir la vie quotidienne. Expliquer que stabilisation et gain visuel sont possibles, sans garantir le retour à la vision antérieure.')+
'<h3>11.B — Moyens</h3>'+paras('La forme exsudative peut bénéficier d’injections répétées d’inhibiteurs du facteur de croissance de l’endothélium vasculaire (VEGF). La présentation d’aflibercept documentée ici illustre un schéma suisse précis : ')+eylea+paras('Ce schéma ne s’applique ni à tous les anti-VEGF ni à toutes les concentrations d’aflibercept. Le choix ou un changement de produit tient compte de l’activité, de la réponse, des risques et des conditions d’accès. Aucun remboursement individuel n’est affirmé à partir de la seule présence d’une autorisation.',
'Pour une forme atrophique, surveillance et réadaptation restent essentielles. Certains stades peuvent justifier une discussion de compléments nutritionnels avec l’ophtalmologue ; ce n’est pas une prescription universelle ni un moyen de régénérer la macula. Aucune formule ou dose de complément n’est improvisée.',
'Une annonce de traitement à l’étranger ne prouve pas son autorisation en Suisse. La page de l’Agence européenne des médicaments (EMA) consultée décrit le refus de Syfovre pour l’atrophie géographique. Cette décision européenne n’est pas présentée comme une décision suisse, et aucun schéma de ce médicament n’est proposé ici.',
'Adapter éclairage, contraste, moyens grossissants et outils numériques. La réadaptation basse vision peut améliorer l’usage de la vision restante. Rechercher les difficultés d’autonomie et la souffrance liée au handicap, sans attendre l’épuisement des options ophtalmologiques.')+
'<h3>11.C — Surveillance</h3>'+paras('L’évaluation de la vision et de la morphologie guide les intervalles. Une amélioration ne justifie pas l’arrêt autonome des injections. Si un rendez-vous est manqué, contacter l’équipe pour organiser la suite plutôt que choisir une nouvelle date sans avis.',
'L’asepsie, la surveillance de la pression et l’information sur les complications font partie du geste. Signaler les allergies précises et les infections ; ne pas interrompre seul les traitements habituels. Les conseils généraux d’une brochure ne remplacent pas l’ordonnance et le protocole du centre.',
'Entre les visites, surveiller séparément chaque œil selon les consignes reçues. Toute déformation ou baisse nouvelle doit être signalée, même si le contrôle précédent était rassurant. Un autotest ne remplace pas l’imagerie ni l’évaluation médicale.')+
'<h3>11.D — Pronostic et suivi</h3>'+paras('Le pronostic dépend du stade, de l’activité et des lésions déjà constituées. La vision périphérique peut rester utile malgré une atteinte centrale sévère. Cette conservation ne permet pas de nier le handicap ni de promettre une capacité de conduite.',
'L’arrêt ou l’espacement est une décision individualisée. Les besoins d’aide, de suivi de l’autre œil et de réadaptation persistent après une décision de ne plus injecter. Réévaluer le projet de soins avec le patient.'),(42,43,44,45,46,47,48))
l.add('La {prévention et l’éducation} associent arrêt du tabac, surveillance et accès aux soins. Les conseils doivent rester adaptés au stade de la maladie. Une alimentation équilibrée ou un complément ne remplace pas une injection indiquée.',paras('Soutenir l’arrêt du tabac et les habitudes favorables à la santé. Une indication de complément se discute avec l’ophtalmologue selon le stade et le terrain, en vérifiant sa composition et ses risques. Ne pas additionner spontanément plusieurs préparations.',
'Donner les signes de changement à surveiller et le moyen de joindre l’équipe. Prévoir un support écrit lisible et vérifier la compréhension. L’aide d’un proche peut faciliter rendez-vous et transport avec l’accord du patient.',
'La bonne vision d’un œil peut masquer la baisse de l’autre. Les examens séparés et le suivi adapté permettent de ne pas attendre un handicap bilatéral pour consulter.'),(42,43,44,47))
l.add('Les {points clés} sont la forme, l’activité et la continuité du suivi. Une DMLA peut limiter fortement la vie quotidienne sans supprimer toute vision périphérique. La dose d’un traitement intravitréen reste propre à son produit et à sa présentation.',steps('Faire évaluer toute métamorphopsie ou baisse centrale nouvelle.','Distinguer forme atrophique et composante néovasculaire active.','Associer fonction visuelle, examen et imagerie.','Vérifier concentration, volume, calendrier et contre-indications avant injection.','Ne pas injecter tout le contenu d’une seringue conçue avec un excédent.','Prendre au sérieux douleur, rougeur ou baisse après injection.','Maintenir le suivi et la réadaptation, même lorsque le gain visuel reste limité.'),(13,42,43,44,48))
l.quiz([
('Question 1 — Une baisse centrale chez une personne âgée est-elle toujours un vieillissement normal ?', 'Non. Il faut rechercher une maladie maculaire et les autres causes de baisse visuelle.'),
('Question 2 — Une vision périphérique conservée signifie-t-elle absence de handicap ?', 'Non. Lecture et reconnaissance des visages peuvent être fortement compromises.'),
('Question 3 — Une grille d’Amsler normale suffit-elle à exclure une activité ?', 'Non. L’autosurveillance ne remplace pas l’examen et l’imagerie.'),
('Question 4 — Une déformation nouvelle peut-elle attendre le prochain contrôle habituel ?', 'Non. Elle doit être signalée rapidement afin de rechercher une activité traitable.'),
('Question 5 — L’OCT renseigne-t-il seulement sur l’acuité ?', 'Non. Il décrit la structure et notamment la présence de liquide ; il complète la mesure fonctionnelle.'),
('Question 6 — Les anti-VEGF régénèrent-ils les cellules perdues dans toute forme atrophique ?', 'Non. Ils visent la composante néovasculaire lorsque le traitement est indiqué ; les objectifs doivent rester réalistes.'),
('Question 7 — Le schéma suisse Eylea 2 mg est-il celui de toutes les présentations ?', 'Non. La forme 2 mg/50 µl a sa notice et son calendrier, non transposables à la forme 8 mg/70 µl ni à un autre produit.'),
('Question 8 — Faut-il injecter tout le volume de la seringue préremplie 2 mg ?', 'Non. Elle contient un excédent. La dose adulte visée est 2 mg dans 50 µl avec préparation correcte du repère.'),
('Question 9 — Le rythme reste-t-il nécessairement mensuel à vie ?', 'Non. La notice de cette présentation permet une adaptation selon vision et morphologie après le début du traitement. Le spécialiste définit le calendrier.'),
('Question 10 — Une infection oculaire permet-elle une injection avec simple surveillance ?', 'Non. Elle figure dans les contre-indications de la notice citée et doit être évaluée avant toute administration.'),
('Question 11 — Une pression intraoculaire élevée peut-elle être ignorée avant Eylea ?', 'Non. La notice demande de ne pas injecter tant que la pression est au moins 30 mmHg et de surveiller après injection.'),
('Question 12 — Suspendre une injection pour une déchirure permet-il d’attendre sans soins ?', 'Non. La complication nécessite sa prise en charge ; la règle de suspension ne supprime pas l’urgence.'),
('Question 13 — Une douleur et une baisse après injection sont-elles forcément normales ?', 'Non. Elles imposent un avis urgent, notamment pour rechercher une infection ou une hyperpression.'),
('Question 14 — Une stabilisation autorise-t-elle à abandonner suivi et réadaptation ?', 'Non. Le calendrier et l’éventuel arrêt sont discutés médicalement ; les besoins fonctionnels et l’autre œil restent suivis.')
],(13,42,43,44,46,47,48))
l.write()
